  // Help page
  "help.eyebrow": "Help Center",
  "help.title": "How can we help?",
  "help.subtitle": "TYRO guides, common questions and support contacts.",
  "help.sections.support": "Support contacts",
  "help.sections.supportSubtitle": "Reach us if you did not find what you were looking for",
  "help.faq.q1": "Why does an assistant look locked?",
  "help.faq.a1":
    "Assistants and AI products open according to the app list an administrator defined for you; if one is not on your list it shows as locked. Press Request access on its card on Home and add a reason; you can follow the status in My Profile › Access.",
  "help.faq.q2": "I cannot see the Catalog section in My Profile.",
  "help.faq.a2":
    "Editing the catalog (assistants, AI products, business apps) is open to the admin group. You can check your own status under My Profile › Access.",
  "help.faq.q3": "Where are definitions and preferences stored?",
  "help.faq.a3":
    "The assistant and app catalog lives in Dataverse — everyone sees the same list. Mode, theme, language and favourites live only in this browser (localStorage); My Profile › This browser lists them. Mail, calendar and file contents are held in memory only and are wiped on sign-out.",
  "help.faq.q4": "Calendar, mail or files say access is not approved.",
  "help.faq.a4":
    "The panels run on Microsoft Graph permissions. The moment a permission is approved in the tenant the panel opens with no code change — ask your IT admin for the permission the panel names (e.g. Mail.Read). Profile photos need a separate permission; without it you see initials.",
  "help.faq.q5": "Are there keyboard shortcuts?",
  "help.faq.a5":
    "Ctrl/⌘+K opens search: people, offices, pages, files and quick actions. In chat Enter sends, Shift+Enter adds a new line, and Esc closes the side panel.",
  "help.faq.q6": "How do I add favourites, and where do they go?",
  "help.faq.a6":
    "Use the heart that appears on a card, or the second row of the app menu in the sidebar. The list is written to this browser; a renamed app shows its new name, one dropped from the catalog stops being listed — but your favourite is never deleted.",
  "help.faq.q7": "Can I install the app on my phone?",
  "help.faq.a7":
    "Yes. Tap Install TYRO in the user menu (or the Install button below); the app opens in its own window, or from the home screen on a phone. On iPhone and iPad the same item shows Safari's two-step guide.",
  "help.faq.q8": "Which interface languages are available?",
  "help.faq.a8": "Turkish, English, Russian and Arabic.",
  "help.support.email.title": "Send an email",
  "help.support.teams.title": "Message on Teams",
  "help.search.placeholder": "Search guides and answers",
  "help.search.aria": "Search this help page",
  "help.search.empty": "That word does not appear on this page.",
  "help.search.emptyHint":
    "Try another word, or write to the support contacts below — if the answer is not here, it needs to be written.",
  "help.search.hint": "Searches the guides and the FAQ. Shortcut: /",
  "help.search.clear": "Clear search",
  "help.popular": "Popular",
  "help.popular.1": "shortcut",
  "help.popular.2": "locked assistant",
  "help.popular.3": "notification",
  "help.popular.4": "favourite",
  "help.popular.5": "permission",
  "help.faq.q9": "How do I get told when an answer is ready?",
  "help.faq.a9":
    "Grant browser notifications in My Profile; we announce a ready answer even while the tab sits in the background. The same place carries a Test notification button — if nothing appears, the fault is in your operating system's notification settings rather than the browser. Without permission we fall back to the tab title and the badge.",
  "help.nav.aria": "Help sections",
  "help.nav.shortcuts": "Shortcuts",
  "help.nav.support": "Support",
  "help.faq.q10": "How do I open a leave, expense or business advance request?",
  "help.faq.a10":
    "In Self service press New (on phones, the + at the bottom right) and pick the type, or write it as a sentence with Describe. TYRO creates the request in the ERP; you follow its status in the Self service list.",
  "help.faq.q11": "How do I add an expense receipt?",
  "help.faq.a11":
    "In the expense form press Add receipt, use Take photo on a phone or drag the image in. You can also paste lines from Excel. Before sending, the Review page shows everything once more.",
  "help.faq.q12": "What does Describe understand?",
  "help.faq.a12":
    "Dates (“yarın”, “cuma”, “aralık ilk hafta”), the leave type, expense lines (“Opet 2000 benzin”) and the purpose of an advance. It shows what it understood in the form; nothing is sent until you send it. Describe is shown only when the interface is in Turkish, and it understands Turkish sentences only.",
  "help.faq.q13": "What do I see in Discover?",
  "help.faq.a13":
    "Your personal work notifications in one feed. In Find you search people, offices, your recent files and email attachments; tap an attachment to preview it. You can like, share or save a post.",
  "help.faq.q14": "Is To-Do the same as Microsoft To Do?",
  "help.faq.a14":
    "Yes. The To-Do page uses your Microsoft To Do lists; a task you add or complete here also shows in To Do in Outlook and Teams.",
  "help.faq.q15": "What does “Your session has expired” mean?",
  "help.faq.a15":
    "For security, your session is renewed at intervals. Press Sign in again in the notice; usually you continue where you left off without a password.",
  "help.faq.copyLink": "Copy link",
  "help.faq.copied": "Link copied",
