  "help.support.whatsNew.value": "Latest features and fixes",
  "help.support.prefill": "I was searching the Help page for “{query}”.",
  "help.sections.pages": "Guide, page by page",
  "help.nav.pages": "Pages",
  "help.nav.tours": "Guided tours",
  "help.group.functions": "What you can do",
  "help.group.faq": "Common questions",
